import {localDate,normalizeTask,decodeTasks,matchesView,selectTasks,summary,mergeTasks,csv} from './core.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],KEY='work-todo-v1',THEME='work-todo-theme';
let tasks=[],selected=new Set(),editingId=null,undoTasks=null,toastTimer,readBlocked=false;
let state={view:'all',filter:'all',query:'',category:'',priority:'',sort:'created'};
const names={all:'全部任务',today:'今日到期',upcoming:'未来七天',overdue:'已逾期',starred:'星标任务',trash:'回收站'};
try{tasks=decodeTasks(JSON.parse(localStorage.getItem(KEY)||'[]'));document.documentElement.dataset.theme=localStorage.getItem(THEME)||'light';}catch{readBlocked=true;}
function announce(text,undo=false){clearTimeout(toastTimer);$('#toast span').textContent=text;$('#undo').hidden=!undo;$('#toast').hidden=false;toastTimer=setTimeout(()=>{$('#toast').hidden=true;},undo?15000:6000);}
function save(){try{if(readBlocked)throw Error();localStorage.setItem(KEY,JSON.stringify(tasks));$('#save-label').textContent='已自动保存';return true;}catch{$('#save-label').textContent='保存失败，请导出备份';announce('无法保存到浏览器，请导出备份。原有存储未被覆盖。');return false;}}
function mutate(action,message,{undo=false}={}){const before=structuredClone(tasks);action();undoTasks=undo?before:null;const saved=save();render();if(saved)announce(message,undo);}
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function button(text,label,handler,cls=''){const b=node('button',cls,text);b.type='button';b.setAttribute('aria-label',label);b.addEventListener('click',handler);return b;}
function render(){
 const today=localDate(),stats=summary(tasks,today),categories=[...new Set(tasks.filter(t=>!t.deleted).map(t=>t.category).filter(Boolean))].sort();
 if(state.category&&!categories.includes(state.category))state.category='';const visible=selectTasks(tasks,{...state,today});
 $('#remaining').textContent=stats.pending;$('#today-count').textContent=stats.today;$('#done-count').textContent=stats.done;$('#progress').value=stats.progress;$('#progress-text').textContent=`${stats.progress}%`;$('#progress-detail').textContent=`共 ${stats.total} 项，已完成 ${stats.done} 项`;
 $('#view-title').textContent=names[state.view];
 $$('[data-view]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.view===state.view);b.querySelector('b').textContent=tasks.filter(t=>matchesView(t,b.dataset.view,today)).length;});
 $$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===state.filter));
 $('#category-filter').replaceChildren(new Option('全部分类',''),...categories.map(c=>new Option(c,c)));$('#category-filter').value=state.category;$('#categories').replaceChildren(...categories.map(c=>new Option(c,c)));
 const visibleIds=new Set(visible.map(t=>t.id));selected=new Set([...selected].filter(id=>visibleIds.has(id)));$('#list').replaceChildren(...visible.map(t=>renderTask(t,today)));
 $('#selection-count').textContent=`已选 ${selected.size} 项`;$('#select-all').checked=visible.length>0&&selected.size===visible.length;$('#select-all').indeterminate=selected.size>0&&selected.size<visible.length;
 const trash=state.view==='trash';$('#batch-done').hidden=trash;$('#batch-delete').hidden=trash;$('#batch-restore').hidden=!trash;['#batch-done','#batch-delete','#batch-restore'].forEach(s=>$(s).disabled=!selected.size);
 $('#empty').hidden=visible.length>0;$('#empty h3').textContent=trash?'回收站是空的':tasks.some(t=>!t.deleted)?'这里暂时没有任务':'从一件小事开始';$('#empty p').textContent=trash?'移入回收站的任务可以在这里恢复。':'试试新建任务，或调整搜索与筛选条件。';$('#empty-add').hidden=trash;
 $('#result-count').textContent=`显示 ${visible.length} 项 · ${trash?'回收站':'全部'}共 ${trash?tasks.filter(t=>t.deleted).length:stats.total} 项`;updateThemeButton();
}
function renderTask(t,today){
 const li=node('li','task'+(t.done?' done':'')),row=node('div','task-row'),pick=node('input','pick');pick.type='checkbox';pick.checked=selected.has(t.id);pick.setAttribute('aria-label',`选择任务：${t.text}`);pick.addEventListener('change',()=>{if(pick.checked)selected.add(t.id);else selected.delete(t.id);render();});
 const check=node('input','complete');check.type='checkbox';check.checked=t.done;check.disabled=t.deleted;check.setAttribute('aria-label',`完成任务：${t.text}`);check.addEventListener('change',()=>mutate(()=>{t.done=check.checked;},check.checked?'任务已完成':'已恢复为未完成'));
 const body=node('div','task-body'),title=node('div','task-title',t.text),meta=node('div','task-meta');body.append(title,meta);
 if(t.priority!=='normal')meta.append(node('span','pill '+t.priority,t.priority==='high'?'高优先级':'低优先级'));
 if(t.due)meta.append(node('span','due'+(!t.done&&t.due<today?' overdue':''),(!t.done&&t.due<today?'已逾期 · ':t.due===today?'今天 · ':'截止 ')+t.due));
 if(t.category)meta.append(node('span','pill category',t.category));const subCount=node('span','sub-count',`${t.subtasks.filter(s=>s.done).length}/${t.subtasks.length} 子任务`);if(t.subtasks.length)meta.append(subCount);
 if(t.notes)body.append(node('p','notes',t.notes));const actions=node('div','task-actions');
 if(t.deleted)actions.append(button('恢复',`恢复任务：${t.text}`,()=>mutate(()=>{t.deleted=false;},'任务已恢复')));
 else{const star=button(t.starred?'★':'☆',`星标任务：${t.text}`,()=>{const next=!t.starred;mutate(()=>{t.starred=next;},next?'已设为星标':'已取消星标');},'star');star.setAttribute('aria-pressed',t.starred);actions.append(star,button('编辑',`编辑任务：${t.text}`,()=>openEditor(t)),button('删除',`删除任务：${t.text}`,()=>mutate(()=>{t.deleted=true;},'已移入回收站，可恢复',{undo:true})));}
 row.append(pick,check,body,actions);li.append(row);
 if(t.subtasks.length){const details=node('details','subtasks');details.append(node('summary','',`查看 ${t.subtasks.length} 项子任务`));t.subtasks.forEach(s=>{const label=node('label'),c=node('input');c.type='checkbox';c.checked=s.done;c.disabled=t.deleted;c.setAttribute('aria-label',`子任务：${s.text}`);c.addEventListener('change',()=>{s.done=c.checked;undoTasks=null;if(save())announce('子任务已保存');subCount.textContent=`${t.subtasks.filter(x=>x.done).length}/${t.subtasks.length} 子任务`;});label.append(c,node('span','',s.text));details.append(label);});li.append(details);}return li;
}
function openEditor(task){editingId=task?.id||null;const f=$('#edit-form');f.reset();$('#edit-title').setCustomValidity('');$('#editor-title').textContent=task?'编辑任务':'新建任务';f.elements.title.value=task?.text||'';f.elements.due.value=task?.due||'';f.elements.priority.value=task?.priority||'normal';f.elements.category.value=task?.category||'';f.elements.notes.value=task?.notes||'';f.elements.starred.checked=task?.starred||false;f.elements.subtasks.value=task?.subtasks.map(s=>s.text).join('\n')||'';$('#editor').showModal();$('#edit-title').focus();}
$('#edit-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,text=f.elements.title.value.trim();if(!text){$('#edit-title').setCustomValidity('请输入任务名称');$('#edit-title').reportValidity();return;}const old=tasks.find(t=>t.id===editingId);if(editingId&&!old){announce('该任务已在另一标签页删除，请关闭后重试');return;}const pool=[...(old?.subtasks||[])],subtasks=f.elements.subtasks.value.split('\n').map(s=>s.trim()).filter(Boolean).slice(0,100).map(text=>{const i=pool.findIndex(s=>s.text===text);return i>=0?pool.splice(i,1)[0]:{text,done:false};});const next=normalizeTask({...old,text,due:f.elements.due.value,priority:f.elements.priority.value,category:f.elements.category.value,notes:f.elements.notes.value,starred:f.elements.starred.checked,subtasks});mutate(()=>{if(old)tasks[tasks.indexOf(old)]=next;else tasks.push(next);},old?'任务已更新':'任务已添加');$('#editor').close();});
$('#edit-title').addEventListener('input',()=>$('#edit-title').setCustomValidity(''));['#new-task','#empty-add'].forEach(s=>$(s).addEventListener('click',()=>openEditor()));['#cancel-editor','#close-editor'].forEach(s=>$(s).addEventListener('click',()=>$('#editor').close()));
$('#quick-form').addEventListener('submit',e=>{e.preventDefault();const text=$('#quick-title').value.trim();if(!text)return;mutate(()=>tasks.push(normalizeTask({text})),'任务已添加');$('#quick-title').value='';});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{state.view=b.dataset.view;selected.clear();render();}));$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;selected.clear();render();}));$('#search').addEventListener('input',e=>{state.query=e.target.value;render();});[['#category-filter','category'],['#priority-filter','priority'],['#sort','sort']].forEach(([s,key])=>$(s).addEventListener('change',e=>{state[key]=e.target.value;render();}));
$('#reset').addEventListener('click',()=>{state={...state,filter:'all',query:'',category:'',priority:'',sort:'created'};$('#search').value='';$('#priority-filter').value='';$('#sort').value='created';render();});
$('#select-all').addEventListener('change',e=>{selected=e.target.checked?new Set(selectTasks(tasks,state).map(t=>t.id)):new Set();render();});$('#batch-done').addEventListener('click',()=>mutate(()=>{tasks.filter(t=>selected.has(t.id)).forEach(t=>t.done=true);selected.clear();},'所选任务已完成',{undo:true}));$('#batch-delete').addEventListener('click',()=>mutate(()=>{tasks.filter(t=>selected.has(t.id)).forEach(t=>t.deleted=true);selected.clear();},'所选任务已移入回收站',{undo:true}));$('#batch-restore').addEventListener('click',()=>mutate(()=>{tasks.filter(t=>selected.has(t.id)).forEach(t=>t.deleted=false);selected.clear();},'所选任务已恢复'));
$('#undo').addEventListener('click',()=>{if(undoTasks){tasks=undoTasks;undoTasks=null;const saved=save();selected.clear();render();if(saved)announce('已撤销上一次操作');}});$('#dismiss').addEventListener('click',()=>$('#toast').hidden=true);
function download(content,type,extension){const url=URL.createObjectURL(new Blob([content],{type})),a=node('a');a.href=url;a.download=`工作待办-${localDate()}.${extension}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export-json').addEventListener('click',()=>download(JSON.stringify({version:2,exportedAt:new Date().toISOString(),tasks},null,2),'application/json','json'));$('#export-csv').addEventListener('click',()=>download(csv(tasks),'text/csv;charset=utf-8','csv'));$('#import').addEventListener('click',()=>$('#import-file').click());$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('备份文件不能超过 10 MB');const incoming=decodeTasks(JSON.parse(await file.text())),merged=mergeTasks(tasks,incoming);mutate(()=>{tasks=merged.tasks;},`已导入 ${merged.added} 项，重复任务已跳过`,{undo:true});}catch(error){announce('导入失败：'+(error instanceof SyntaxError?'文件不是有效的 JSON':error.message));}finally{e.target.value='';}});
function updateThemeButton(){$('#theme').textContent=document.documentElement.dataset.theme==='dark'?'切换浅色模式':'切换深色模式';}$('#theme').addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem(THEME,theme);}catch{}updateThemeButton();});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select')||$('#editor').open)return;if(e.key.toLowerCase()==='n'){e.preventDefault();openEditor();}if(e.key==='/'){e.preventDefault();$('#search').focus();}});
function dateHeader(){$('#date-label').textContent=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});}
window.addEventListener('storage',e=>{if(e.key===KEY&&!readBlocked){try{tasks=decodeTasks(JSON.parse(e.newValue||'[]'));undoTasks=null;selected.clear();render();announce('已同步此浏览器另一标签页的更改');}catch{announce('另一标签页的数据格式有误，请先导出备份');}}});document.addEventListener('visibilitychange',()=>{if(!document.hidden){dateHeader();render();}});dateHeader();render();if(readBlocked)announce('已有记录无法读取。为保护原数据，暂不覆盖存储，请先检查浏览器设置或备份。');
